// src/facets/weather.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds snowing: bool, sky: Vec<(Vec3, Particles)> and dust: Option<Particles>.
use super::World;
use genex::Particles;
use genex::prelude::*;

/// The weather tiles: a 3 x 3 grid of 20 m boxes over a 60 m yard (a larger world takes more,
/// at most about 14 with the dust: the renderer holds 16 different emitters).
const TILE: f32 = 20.0;
const TILES: u32 = 3;
/// The boxes' top: rain falls 9 m in its second of life, snow in about 9 s.
const SKY_Y: f32 = 9.0;

/// One rain or snow box per tile, made once: a box moved each frame would be a new emitter.
fn sky(snowing: bool) -> Vec<(Vec3, Particles)> {
    let half = vec3(TILE * 0.5, 0.0, TILE * 0.5);
    let mut tiles = Vec::new();
    for i in 0..TILES * TILES {
        let centre = vec3(((i % TILES) as f32 - 1.0) * TILE, SKY_Y, ((i / TILES) as f32 - 1.0) * TILE);
        let tile = if snowing { Particles::snow(centre, half) } else { Particles::rain(centre, half) };
        tiles.push((centre, tile.with_seed(i + 1))); // a seed each, so neighbours differ
    }
    tiles
}

pub fn wire(game: &mut Game<World>) {
    game.on_reset(|sim, _, _, _| {
        // Made at a loading point and kept in the world; the same emitters again after a reset.
        sim.world.sky = sky(sim.world.snowing);
        // Motes in the sunbeam from the hall's window: the box is the beam (they are not lit).
        sim.world.dust = Some(Particles::dust(vec3(4.0, 1.4, -6.0), vec3(0.8, 1.2, 2.5)));
    });
    game.on_draw(|sim, frame, camera| {
        let at = vec2(camera.position.x, camera.position.z);
        frame.tag("weather"); // counts the draws that follow
        for (centre, tile) in &sim.world.sky {
            // The tiles within one tile of the camera: weather at least 10 m all round, wherever it goes.
            if (vec2(centre.x, centre.z) - at).length() < TILE {
                frame.particles(tile);
            }
        }
        if let Some(dust) = &sim.world.dust {
            frame.tag("dust").particles(dust);
        }
    });
}
